use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let jobs: Vec<[i64; 2]> = serde_json::from_value(input).unwrap();
    let mut total_wait_time = 0;
    let mut current_time = 0;

    for job in jobs {
        let arrival = job[0];
        let duration = job[1];

        if arrival > current_time {
            total_wait_time += arrival - current_time;
            current_time = arrival;
        }

        current_time += duration;
    }

    serde_json::Value::Number(serde_json::Number::from(total_wait_time))
}
